test('747 actual C++ resize uses an exact inward change and keeps every foreground and API refusal',()=>{
 const old=resizeInverseCpp747(activationInverseCpp747(cpp.replace(/\r\n/g,'\n')))
 assert.equal(createHash('sha256').update(old).digest('hex'),'d99e82668a28f5965b545b0f72b1d0c3954f058bc36b5d26b5368f2f93f1c486')
 function run(raw:string,fault='none'){
  const signature='void D705TerminalAcceptance::resize(';assert.equal(raw.split(signature).length,2)
  const body=block(raw,raw.indexOf(signature)).replace('RECT before{},after{};','let before={},after={};').replace(/nullptr/g,'null').replace(/&before/g,'before').replace(/&after/g,'after')
  let width=1024,reads=0;const failures:number[]=[],requests:number[]=[],window={},h={window},c:any={h,window,typed:true,resized:false,key_count:6,confirm_count:3,receipt_mask:7,SWP_NOMOVE:1,SWP_NOZORDER:2,SWP_NOACTIVATE:4,current:()=>fault!=='current',GetForegroundWindow:()=>fault==='foreground'?{}:window,failure:(_h:any,site:number)=>failures.push(site),GetWindowRect:(_w:any,out:any)=>{reads++;if(fault===(reads===1?'before':'after'))return false;Object.assign(out,{left:0,top:0,right:width,bottom:760});return true},SetWindowPos:(_w:any,_after:any,_x:number,_y:number,w:number,height:number,flags:number)=>{requests.push(w);assert.equal(height,760);assert.equal(flags,7);if(fault==='set')return false;width=fault==='unchanged'?1024:Math.min(1024,w);return true}}
  if(fault==='typed')c.typed=false;if(fault==='keys')c.key_count=5;if(fault==='confirmation')c.confirm_count=2;if(fault==='receipt')c.receipt_mask=3;if(fault==='repeat')c.resized=true
  vm.runInNewContext('(function(){'+body+'})()',c,{timeout:1000});return{failures,requests,width,reads}
 }
 const preceding=run(old);assert.deepEqual(preceding.failures,[16]);assert.deepEqual(preceding.requests,[1144]);assert.equal(preceding.width,1024)
 const current=run(cpp);assert.deepEqual(current.failures,[]);assert.deepEqual(current.requests,[904]);assert.equal(current.width,904);assert.equal(current.reads,2)
 for(const fault of ['current','foreground','typed','keys','confirmation','receipt','repeat']){const value=run(cpp,fault);assert.deepEqual(value.failures,[15]);assert.deepEqual(value.requests,[])}
 for(const fault of ['before','set','after','unchanged'])assert.deepEqual(run(cpp,fault).failures,[16])
})

